const out = {};
function dump(n, depth) {
  const o = {id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height)};
  if (n.type === 'TEXT') { o.chars = n.characters; o.font = n.fontName; o.size = n.fontSize; try{o.fills=JSON.parse(JSON.stringify(n.fills))}catch(e){} }
  if ('fills' in n && n.type !== 'TEXT') { try { o.fills = JSON.parse(JSON.stringify(n.fills)).map(f=>({type:f.type, color:f.color, opacity:f.opacity, imageRef:f.imageRef, scaleMode:f.scaleMode})); } catch(e){} }
  if ('strokes' in n) { try { o.strokes = JSON.parse(JSON.stringify(n.strokes)); o.strokeWeight = n.strokeWeight; } catch(e){} }
  if ('cornerRadius' in n) o.cornerRadius = n.cornerRadius;
  if ('layoutMode' in n && n.layoutMode !== 'NONE') { o.layoutMode = n.layoutMode; o.itemSpacing = n.itemSpacing; o.padding = [n.paddingTop,n.paddingRight,n.paddingBottom,n.paddingLeft]; o.primaryAlign=n.primaryAxisAlignItems; o.counterAlign=n.counterAxisAlignItems; }
  if (depth > 0 && 'children' in n) o.children = n.children.map(c=>dump(c, depth-1));
  return o;
}
out.button = dump(await figma.getNodeByIdAsync('1:23'), 3);
out.textField = dump(await figma.getNodeByIdAsync('1:26'), 3);
out.photo = dump(await figma.getNodeByIdAsync('1:110'), 2);
