const ws = figma.root.children.find(p=>p.name.includes('Workspace'));
out.workspace = {id: ws.id, name: ws.name, childCount: ws.children.length, children: ws.children.map(c=>({id:c.id,name:c.name,type:c.type}))};
return JSON.stringify(out, null, 1);

