const styles = ['Regular','Medium','SemiBold','Bold','ExtraBold'];
for (const s of styles) { await figma.loadFontAsync({family:'Hanken Grotesk', style:s}); }
const F = (s)=>({family:'Hanken Grotesk', style:s});
const BLACK={r:0,g:0,b:0}, WHITE={r:1,g:1,b:1}, GRAY={r:0.47,g:0.47,b:0.47}, LGRAY={r:0.62,g:0.62,b:0.62}, RULE={r:0.88,g:0.88,b:0.88}, TINT={r:0.96,g:0.96,b:0.96};
const solid=(c,o)=>[{type:'SOLID',color:c,opacity:o===undefined?1:o}];

async function txt(chars, font, size, color, opts={}) {
  const t = figma.createText(); t.fontName=F(font); t.characters=chars; t.fontSize=size;
  t.fills=solid(color);
  if (opts.lh) t.lineHeight={value:opts.lh, unit:'PIXELS'};
  if (opts.ls) t.letterSpacing={value:opts.ls, unit:'PIXELS'};
  if (opts.name) t.name=opts.name;
  if (opts.width) { t.textAutoResize='HEIGHT'; t.resize(opts.width, t.height); }
  return t;
}
function al(dir, spacing, pad, opts={}) {
  const f = figma.createFrame(); f.layoutMode=dir; f.itemSpacing=spacing||0;
  f.paddingTop=pad?pad[0]:0; f.paddingRight=pad?pad[1]:0; f.paddingBottom=pad?pad[2]:0; f.paddingLeft=pad?pad[3]:0;
  f.primaryAxisAlignItems=opts.primary||'MIN'; f.counterAxisAlignItems=opts.counter||'MIN';
  f.primaryAxisSizingMode=opts.fixW?'FIXED':'AUTO'; f.counterAxisSizingMode=opts.fixH?'FIXED':'AUTO';
  f.fills=opts.fills||[]; if(opts.name)f.name=opts.name;
  if (opts.clips) f.clipsContent=true;
  return f;
}
const MEDIA = {
  arrowR:'1:93', arrowL:'1:92', arrowD:'1:91', ig:'1:94', tw:'1:96', yt:'1:97', rss:'1:95',
  spotify:'1:100', apple:'1:98', soundcloud:'1:99'
};
async function icon(key, size, color) {
  const c = await figma.getNodeByIdAsync(MEDIA[key]);
  const i = c.createInstance(); i.resize(size,size);
  if (color) { const walk=(n)=>{ if('fills' in n && n.type==='VECTOR'){ n.fills=solid(color);} if('children' in n) n.children.forEach(walk); }; walk(i); }
  return i;
}
function comp(name, node) {
  const c = figma.createComponentFromNode(node); c.name=name; return c;
}

// ---------- Header component set (variants: Current) ----------
async function buildHeader(current) {
  const root = al('HORIZONTAL', 0, [0,80,0,80], {name:'Header', counter:'CENTER', fixW:true, fixH:true, fills:solid(WHITE)});
  root.resize(1680, 96);
  const wm = await txt('FYRRE MAGAZINE','ExtraBold',22,BLACK,{ls:1});
  root.appendChild(wm);
  const nav = al('HORIZONTAL', 48, [0,0,0,0], {counter:'CENTER', primary:'CENTER'});
  nav.layoutGrow=1; nav.layoutAlign='STRETCH';
  for (const item of ['Magazine','Authors','Podcast']) {
    const isCur = item===current;
    const wrap = al('VERTICAL',4,[0,0,4,0],{counter:'CENTER'});
    const t = await txt(item, isCur?'Bold':'Medium', 16, isCur?BLACK:LGRAY);
    wrap.appendChild(t);
    const ul = figma.createRectangle(); ul.resize(40,2); ul.fills=solid(isCur?BLACK:WHITE, isCur?1:0);
    wrap.appendChild(ul);
    nav.appendChild(wrap);
  }
  root.appendChild(nav);
  const soc = al('HORIZONTAL', 20, [0,0,0,0], {counter:'CENTER'});
  for (const k of ['ig','tw','yt','rss']) soc.appendChild(await icon(k,20,BLACK));
  root.appendChild(soc);
  const line = figma.createRectangle(); line.resize(1680,1); line.fills=solid(RULE);
  const holder = figma.createFrame(); holder.name='HeaderHolder'; holder.appendChild(root); holder.appendChild(line);
  line.x=0; line.y=95; holder.resize(1680,96); holder.fills=[]; holder.clipsContent=true;
  return comp('Header', holder);
}
