// Fix sizing: for VERTICAL frames, width=counter axis FIXED, height=primary AUTO.
// For HORIZONTAL frames, width=primary FIXED, height=counter AUTO.
const fix=(n,targetW)=>{
  if(n.layoutMode==='VERTICAL'){n.counterAxisSizingMode='FIXED';n.primaryAxisSizingMode='AUTO';n.resize(targetW,n.height);}
  else if(n.layoutMode==='HORIZONTAL'){n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='AUTO';n.resize(targetW,n.height);}
};
// page
fix(page,1680);
// walk direct children sections
for(const c of page.children){
  if(c.type!=='FRAME')continue;
  if(c.name==='Header'||c.name==='NewsTicker'||c.name==='Footer')continue; // instances, already sized
  fix(c,1680);
  // inner columns
  for(const g of c.children){
    if(g.type!=='FRAME')continue;
    if(g.layoutMode==='HORIZONTAL'&&g.width>1000){ // lead row, main row, epRow, auRow
      // keep width fixed; height auto
      g.primaryAxisSizingMode='FIXED';g.counterAxisSizingMode='AUTO';
      for(const col of g.children){
        if(col.type==='FRAME'&&col.layoutMode==='VERTICAL'){col.counterAxisSizingMode='FIXED';col.primaryAxisSizingMode='AUTO';}
      }
    } else if(g.layoutMode==='VERTICAL'){
      g.counterAxisSizingMode='FIXED';g.primaryAxisSizingMode='AUTO';
    }
  }
}
return JSON.stringify({h:page.height,w:page.width});

