  if (node.type === 'INSTANCE') {
    const compName = node.mainComponent?.name;
    if (compName && compH[compName]) {
      const targetH = compH[compName];
      if (Math.abs(node.height - targetH) > 2) {
        node.resize(node.width, targetH);
      }
    }
  }
  if (node.children) {
    node.children.forEach(resizeInstances);
  }
};

