const setT=async(t,s)=>{
  if(!t||t.type!=='TEXT')return;
  if(t.fontName===figma.mixed){
    const len=t.characters.length;
    const fonts=new Set();
    for(let i=0;i<len;i++){
      const fn=t.getRangeFontName(i,i+1);
      if(fn&&fn!==figma.mixed)fonts.add(JSON.stringify(fn));
    }
    for(const f of fonts)await figma.loadFontAsync(JSON.parse(f));
  } else if(t.fontName) {
    await figma.loadFontAsync(t.fontName);
  }
  t.characters=s;
};

const swapPhoto=(parent,idx,compName,w,h)=>{
  const photoComp=ws.findOne(n=>n.type==='COMPONENT'&&n.name===compName);
  if(!photoComp)return;
  const old=parent.children[idx];
  const np=photoComp.createInstance();
  np.resize(w,h);
  parent.insertChild(idx,np);
  old.remove();
};

