const links=[];
const walk=(n,page)=>{
  if(n.reactions&&n.reactions.length){
    n.reactions.forEach(r=>{
      r.actions.forEach(a=>{
        if(a.destinationId)links.push(page+' :: '+(n.name||n.type)+' -> '+(idToName[a.destinationId]||a.destinationId));
      });
    });
  }
  if(n.children)n.children.forEach(c=>walk(c,page));
};
Object.entries(P).forEach(([k,p])=>walk(p,k));
return JSON.stringify(links);

