  x+=c.width+160;
  rowH=Math.max(rowH,c.height);
});
return JSON.stringify(comps.map(c=>({name:c.name,x:Math.round(c.x),y:Math.round(c.y)})));

const ws = figma.root.children.find(p=>p.name.includes('Workspace'));
await figma.setCurrentPageAsync(ws);
const order=['01_Frontpage','02_Magazine','03_Magazine_Post','04_Podcast','05_Podcast_Post','06_Authors','07_Author_Profile'];
const out=order.map(n=>{const f=ws.children.find(c=>c.name===n);return {name:n,id:f.id,w:Math.round(f.width),h:Math.round(f.height)};});
// verify reference pages untouched
const pages=figma.root.children.map(p=>({name:p.name,childCount:p.children.length}));
// final collapsed-frame scan
const bad=[];
const scan=(n,path)=>{
  if((n.type==='FRAME'||n.type==='INSTANCE')&&n.height<=12&&n.width>50&&!/Rule|Divider|Spacer/.test(n.name))bad.push(path);
  if(n.children)n.children.forEach(c=>scan(c,path+'/'+c.name));
};
order.forEach(n=>{const f=ws.children.find(c=>c.name===n);scan(f,n);});
return JSON.stringify({frames:out,pages,badCount:bad.length,bad:bad.slice(0,10)});
